import { beforLogin } from "@/layout/login";
import app from "@/store/app";
import codeApp from "@code/store/app";
import { Spin } from "@arco-design/web-react";
import { useState, Fragment, useEffect } from "react";
import { BrowserRouter, HashRouter, Router, useHistory, useParams } from "react-router-dom";
import DesignSetting, { settingStore } from "./components/DesignSetting";
import { MobileKey } from "@/types/mobile";
import { IframeDesignProps } from "@/types/iframe";
import { useObserver } from "mobx-react-lite";
import userStore from "@/store/userStore";
import language from "@/store/language";
import pageStore from '@/store/page';
import file from "@/store/file";
import design from "@/store/design";
import mainConfig from 'mainConfig';
import { loadScript } from "@/utils/lazyload";
import { moduleStore } from "react-converter-code";
import "@/layout/init";

loadScript(mainConfig.typescriptURL)



const Index = beforLogin(() => {
    const params: any = useParams();
    const { id, path }= params;
    const [store] = useState(() => new settingStore());


    return useObserver(() => {

        const { isReady, setIsReady } = store;

        useEffect(() => {
            app.getAppInfo(id).then(() => {
                setIsReady(true);
            })
        },[])
    
        /**
         * 监听App 页面事件
         */
        useEffect(() => {
            const handleMessage = (event) => {
                if(typeof event.data == "object"){
                    const { key } = event.data;
                    switch(key){
                        case MobileKey.IframeAppReady:
                            // 更新状态
                            store.setIsFrameReady(true);
                        break;
                    }
                }
            };
        
            window.addEventListener('message', handleMessage);
        
            return () => {
                window.removeEventListener('message', handleMessage);
            };
        }, []);

        useEffect(() => {
            const iframe = store.iframeRef.current;
            if(iframe){
                Object.assign(
                    iframe.contentWindow,
                    {
                        iframeDesign: true,
                        userStore,
                        app,
                        fileStore: file,
                        language,
                        pageStore,
                        design,
                        moduleStore,
                    } as IframeDesignProps
                )
            }
        },[isReady])
    
        return (
            <HashRouter basename={`/preview/${id}`} >
                <div className="h-full w-full flex flex-col ">
                    {store.isFrameReady? (
                        <DesignSetting store={store} key={store.key}/>
                    ): null}
                    {isReady? (
                        <iframe
                            ref={store.iframeRef}
                            src={`${location.origin}/#/${path || ''}`}
                            className="grow"
                        >
                        </iframe>
                    ): null}
                </div>
            </HashRouter>
        )
    })
})


export default Index;
